int process_magic_device_event(struct hid_device *hdev, struct hid_report *report,
                               u8 *data, int size) {
    struct magic_drvdata *drvdata = hid_get_drvdata(hdev);
    int report_id = data[0];

    switch (report_id) {
        case TRACKPAD_REPORT_ID:
            if (size < TRACKPAD_MIN_SIZE)
                return 0;
            // Extract and emit touch events for the trackpad
            extract_touch_points(drvdata, data, size);
            // Handle any trackpad-specific button clicks
            handle_button_clicks(drvdata, data);
            break;

        case MOUSE_REPORT_ID:
            if (size < MOUSE_MIN_SIZE)
                return 0;
            // Extract and emit touch events for the mouse
            extract_touch_points(drvdata, data, size);
            // Report relative movement
            report_relative_movement(drvdata, data);
            break;

        case DOUBLE_REPORT_ID:
            if (size < DOUBLE_MIN_SIZE)
                return 0;
            // Process both touch data and movement from a dual report
            extract_touch_points(drvdata, data, size);
            report_relative_movement(drvdata, data);
            break;

        default:
            return 0;
    }

    // Synchronize the input state
    input_sync(drvdata->input_dev);
    return 1;
}

int magic_touch_process_event(struct hid_device *hdev, struct hid_report *report, u8 *data, int size)
{
    struct magic_touch_data *drvdata = hid_get_drvdata(hdev);
    int ret = 1;

    switch (report->id) {
    case TRACKPAD_REPORT_ID:
        if (size < TRACKPAD_MIN_SIZE) {
            hid_err(hdev, "Invalid trackpad report size %d\n", size);
            return 0;
        }
        ret = process_trackpad(hdev, data, size);
        break;
    case MOUSE_REPORT_ID:
        if (size < MOUSE_MIN_SIZE) {
            hid_err(hdev, "Invalid mouse report size %d\n", size);
            return 0;
        }
        ret = process_mouse(hdev, data, size);
        break;
    case DOUBLE_REPORT_ID:
        if (size < DOUBLE_MIN_SIZE) {
            hid_err(hdev, "Invalid double report size %d\n", size);
            return 0;
        }
        ret = process_double_report(hdev, data, size);
        break;
    default:
        hid_err(hdev, "Unknown report ID %d\n", report->id);
        return 0;
    }

    if (!ret)
        return 0;

    input_sync(drvdata->input);
    return 1;
}

int process_magic_input_event(struct hid_device *hdev, struct hid_report *report, u8 *data, int size)
{
    struct magic_drvdata *drvdata = hid_get_drvdata(hdev);
    struct input_dev *input = drvdata->input;

    switch (report->id) {
    case TRACKPAD_REPORT_ID:
        if (size < TRACKPAD_MIN_SIZE)
            return 0;

        // Process trackpad touch points and motion
        // ...

        // Emit touch events
        input_report_rel(input, REL_X, x_delta);
        input_report_rel(input, REL_Y, y_delta);
        break;

    case MOUSE_REPORT_ID:
        if (size < MOUSE_MIN_SIZE)
            return 0;

        // Process mouse buttons and motion
        // ...

        input_report_key(input, BTN_LEFT, left_button);
        input_report_key(input, BTN_RIGHT, right_button);
        input_report_rel(input, REL_X, x_delta);
        input_report_rel(input, REL_Y, y_delta);
        break;

    case DOUBLE_REPORT_ID:
        if (size < DOUBLE_MIN_SIZE)
            return 0;

        // Process combined mouse and touch data
        // ...

        input_report_key(input, BTN_LEFT, left_button);
        input_report_key(input, BTN_RIGHT, right_button);
        input_report_rel(input, REL_X, x_delta);
        input_report_rel(input, REL_Y, y_delta);
        break;

    default:
        return 0;
    }

    input_sync(input);
    return 1;
}

int process_magic_mouse_event(struct hid_device *hdev, struct hid_report *report, u8 *data, int size)
{
    struct magic_driver_data *drvdata = hid_get_drvdata(hdev);
    int i;
    int ret = 1;

    switch (report->id) {
    case TRACKPAD_REPORT_ID:
        if (size < TRACKPAD_MIN_SIZE) {
            hid_err(hdev, "trackpad report too small: %d\n", size);
            return 0;
        }
        for (i = 0; i < MAX_TOUCH_POINTS; i++) {
            if (drvdata->touches[i].active) {
                drvdata->touches[i].x = get_unaligned_le16(&data[1 + i * TOUCH_SIZE + 0]);
                drvdata->touches[i].y = get_unaligned_le16(&data[1 + i * TOUCH_SIZE + 2]);
                input_report_abs(drvdata->input_dev, ABS_MT_POSITION_X, drvdata->touches[i].x);
                input_report_abs(drvdata->input_dev, ABS_MT_POSITION_Y, drvdata->touches[i].y);
            }
        }

        input_report_key(drvdata->input_dev, BTN_LEFT, data[0] & 0x01);
        input_report_key(drvdata->input_dev, BTN_RIGHT, data[0] & 0x02);
        input_report_rel(drvdata->input_dev, REL_X, get_unaligned_le16(&data[1 + MAX_TOUCH_POINTS * TOUCH_SIZE]));
        input_report_rel(drvdata->input_dev, REL_Y, get_unaligned_le16(&data[1 + MAX_TOUCH_POINTS * TOUCH_SIZE + 2]));
        input_sync(drvdata->input_dev);
        break;

    case MOUSE_REPORT_ID:
        if (size < MOUSE_MIN_SIZE) {
            hid_err(hdev, "mouse report too small: %d\n", size);
            return 0;
        }

        input_report_key(drvdata->input_dev, BTN_LEFT, data[0] & 0x01);
        input_report_key(drvdata->input_dev, BTN_RIGHT, data[0] & 0x02);
        input_report_key(drvdata->input_dev, BTN_MIDDLE, data[0] & 0x04);

        input_report_rel(drvdata->input_dev, REL_X, data[1]);
        input_report_rel(drvdata->input_dev, REL_Y, data[2]);
        input_sync(drvdata->input_dev);
        break;

    case DOUBLE_REPORT_ID:
        if (size < DOUBLE_MIN_SIZE) {
            hid_err(hdev, "double report too small: %d\n", size);
            return 0;
        }

        for (i = 0; i < MAX_TOUCH_POINTS; i++) {
            if (drvdata->touches[i].active) {
                drvdata->touches[i].x = get_unaligned_le16(&data[1 + i * TOUCH_SIZE + 0]);
                drvdata->touches[i].y = get_unaligned_le16(&data[1 + i * TOUCH_SIZE + 2]);
                input_report_abs(drvdata->input_dev, ABS_MT_POSITION_X, drvdata->touches[i].x);
                input_report_abs(drvdata->input_dev, ABS_MT_POSITION_Y, drvdata->touches[i].y);
            }
        }

        input_report_key(drvdata->input_dev, BTN_LEFT, data[0] & 0x01);
        input_report_key(drvdata->input_dev, BTN_RIGHT, data[0] & 0x02);
        input_report_key(drvdata->input_dev, BTN_MIDDLE, data[0] & 0x04);

        input_report_rel(drvdata->input_dev, REL_X, get_unaligned_le16(&data[1 + MAX_TOUCH_POINTS * TOUCH_SIZE]));
        input_report_rel(drvdata->input_dev, REL_Y, get_unaligned_le16(&data[1 + MAX_TOUCH_POINTS * TOUCH_SIZE + 2]));
        input_sync(drvdata->input_dev);
        break;

    default:
        hid_dbg(hdev, "ignoring unknown report id: %d\n", report->id);
        ret = 0;
        break;
    }

    return ret;
}

int magic_process_input_event(struct hid_device *hdev, struct hid_report *report, u8 *data, int size)
{
    struct magic_drvdata *drvdata = hid_get_drvdata(hdev);
    int ret = 0;

    if (!drvdata)
        return 0;

    switch (report->id) {
    case TRACKPAD_REPORT_ID:
        if (size < MIN_TRACKPAD_DATA_SIZE)
            break;
        ret = process_trackpad_data(drvdata, data, size);
        break;
    case MOUSE_REPORT_ID:
        if (size < MIN_MOUSE_DATA_SIZE)
            break;
        ret = process_mouse_data(drvdata, data, size);
        break;
    case DOUBLE_REPORT_ID:
        if (size < MIN_DOUBLE_DATA_SIZE)
            break;
        ret = process_double_data(drvdata, data, size);
        break;
    default:
        break;
    }

    if (ret) {
        input_sync(drvdata->input);
        return 1;
    }

    return 0;
}
